import {studioInsight,choose} from './studio-insight.js';
export function auditEvidence(input,previous=null){
 const now=studioInsight(input),before=previous?studioInsight(previous):null,l=input.language||'en',t=(a,b,c)=>choose(l,a,b,c);
 const records=now.receipt.records,prior=before?.receipt.records||[],key=r=>r.type==='tracking'?'tracking:'+r.player:r.id;
 const currentMap=new Map(records.filter(r=>r.type!=='coverage').map(r=>[key(r),r]));
 const priorMap=new Map(prior.filter(r=>r.type!=='coverage').map(r=>[key(r),r]));
 const added=[],removed=[],changed=[],preserved=[];
 for(const[k,r]of currentMap){const old=priorMap.get(k);if(!old)added.push(r.id);else if(JSON.stringify({...r,id:null,second:null})!==JSON.stringify({...old,id:null,second:null}))changed.push(r.id);else preserved.push(r.id);}
 for(const[k,r]of priorMap)if(!currentMap.has(k))removed.push(r.id);
 const passes=now.m.seen.filter(e=>e.type==='pass'&&e.outcome==='complete'&&e.team==='harbor');
 const metres=passes.reduce((n,e)=>n+e.endPosition[0]-e.start[0],0),equation=passes.map(e=>`(${e.endPosition[0].toFixed(2)} − ${e.start[0].toFixed(2)})`).join(' + ')||'0';
 const progression={value:metres,unit:'m',equation:equation+' = '+metres.toFixed(2)+' m',evidence_ids:passes.length?passes.map(e=>e.id):[now.scope],summary:t(`${passes.length} completed Harbor passes gain ${metres.toFixed(1)} m toward goal, summing each pass’s forward displacement. Carries and intercepted passes are excluded.`,`${passes.length} pases completados de Harbor ganan ${metres.toFixed(1)} m hacia la portería, sumando su desplazamiento. Se excluyen conducciones y pases interceptados.`,`${passes.length} passes completos do Harbor avançam ${metres.toFixed(1)} m em direção ao gol, somando o deslocamento. Conduções e passes interceptados são excluídos.`)};
 const correctedMovement=now.m.corrected&&now.m.time>0;
 const withdrawn=!input.tracking?t('Player movement is unavailable. Withdraw movement and off-ball conclusions.','No hay seguimiento. Retira las conclusiones de movimiento y sin balón.','Sem rastreamento. Retire conclusões de movimento e sem bola.'):correctedMovement?t('Withdraw the original claim that Laurent moved wide.','Retira la afirmación original de que Laurent se abrió.','Retire a afirmação original de que Laurent se abriu.'):t('No movement claim has been withdrawn at this snapshot.','No se ha retirado una afirmación de movimiento en este instante.','Nenhuma afirmação de movimento foi retirada neste instante.');
 const retained=t(`${now.m.seen.length} completed event records remain available at this cutoff.`,`${now.m.seen.length} eventos completados siguen disponibles en este instante.`,`${now.m.seen.length} eventos completos permanecem disponíveis neste instante.`);
 const unknown=t('The records do not establish intent, causation, or an outcome after this cutoff.','Los registros no establecen intención, causalidad ni un resultado posterior.','Os registros não estabelecem intenção, causalidade ou resultado posterior.');
 const beginner=input.tracking?(correctedMovement?t('An off-ball run is a player moving without the ball. Here the corrected record keeps the defender still. We can still describe the passes, but cannot say this defender followed the run.','Un desmarque es moverse sin balón. El registro corregido mantiene quieto al defensor. Podemos describir los pases, pero no afirmar que siguió la carrera.','Uma corrida sem bola é movimento de um jogador sem a bola. O registro corrigido mantém o defensor parado. Podemos descrever os passes, mas não dizer que ele seguiu a corrida.'):t('The ball and the players tell different parts of the story. A pass moves the ball to a teammate; a run without the ball can offer another route. Watch the highlighted trail, but don’t assume it caused the defender’s decision.','El balón y los jugadores cuentan partes diferentes. Un pase lleva el balón a un compañero; una carrera sin balón puede ofrecer otra ruta. Mira la trayectoria, sin asumir que causó la decisión defensiva.','A bola e os jogadores contam partes diferentes. Um passe leva a bola a um colega; uma corrida sem bola pode oferecer outra rota. Veja a trajetória, sem assumir que causou a decisão defensiva.')):t('We still know which recorded passes finished. We have removed the player-position data, so we cannot tell you where players ran.','Aún sabemos qué pases terminaron. Sin los datos de posición no podemos decir dónde corrieron los jugadores.','Ainda sabemos quais passes terminaram. Sem os dados de posição não podemos dizer onde os jogadores correram.');
 const analyst=now.roles[0].summary+' '+progression.summary+' '+t('Assess ball progression separately from defensive displacement; this is a short sequence, not a team-strength estimate.','Evalúa la progresión del balón por separado del desplazamiento defensivo; es una secuencia corta, no una estimación de calidad del equipo.','Avalie a progressão da bola separadamente do deslocamento defensivo; é uma sequência curta, não uma estimativa da força da equipe.');
 const question=t('What evidence would distinguish a coordinated defensive shift from a defender following the runner?','¿Qué evidencia distinguiría un ajuste defensivo coordinado de un defensor siguiendo al corredor?','Que evidência distinguiria um ajuste defensivo coordenado de um defensor seguindo o corredor?');
 return {now,before,delta:{added,removed,changed,preserved,compared:!!before},progression,ledger:[{kind:'withdrawn',text:withdrawn,ids:[now.scope]},{kind:'preserved',text:retained,ids:now.m.seen.map(e=>e.id)},{kind:'uncertain',text:unknown,ids:[now.scope]}],audiences:{beginner,analyst},question};
}
